import{_ as n,o as e,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Prinsip Hanya Mengembalikan Pengetahuan","description":"","frontmatter":{},"headers":[],"relativePath":"id/87-仅回传知识原则.md","filePath":"id/87-仅回传知识原则.md","lastUpdated":null}'),u={name:"id/87-仅回传知识原则.md"};function s(r,a,k,m,d,g){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="prinsip-hanya-mengembalikan-pengetahuan" tabindex="-1">Prinsip Hanya Mengembalikan Pengetahuan <a class="header-anchor" href="#prinsip-hanya-mengembalikan-pengetahuan" aria-label="Permalink to &quot;Prinsip Hanya Mengembalikan Pengetahuan&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>87</td></tr><tr><td>Modul</td><td>Interaksi Antar Bidang dan Aturan Waktu</td></tr><tr><td>Kata Kunci Inti</td><td>Hanya mengembalikan pengetahuan, pemurnian informasi, larangan pengembalian materi, pengkodean pengetahuan, audit pengembalian</td></tr></tbody></table><h2 id="_1-latar-belakang-legislatif-dan-ide-inti-prinsip" tabindex="-1">1. Latar Belakang Legislatif dan Ide Inti Prinsip <a class="header-anchor" href="#_1-latar-belakang-legislatif-dan-ide-inti-prinsip" aria-label="Permalink to &quot;1. Latar Belakang Legislatif dan Ide Inti Prinsip&quot;">​</a></h2><p>Prinsip &quot;hanya mengembalikan pengetahuan&quot; adalah salah satu prinsip mendasar arkeologi antar bidang dan mundurnya waktu peradaban simbiosis neo, asal-usul hukumnya dapat ditelusuri kembali ke Pasal 48 &quot;Konstitusi Symbiosis&quot;: &quot;Materi, energi, dan makhluk hidup apa pun yang diperoleh dari bidang lain atau periode waktu lain tidak boleh dibawa ke bidang自己 tanpa izin khusus; hasil sah dari kegiatan arkeologi terbatas pada pengetahuan dan informasi abstrak.&quot; Penetapan prinsip ini adalah pilihan institusional yang dibuat Hengyuanzhou setelah merangkum pelajaran menyakitkan dari eksplorasi antar bidang awal.</p><p>Pada awal pembentukan peradaban simbiosis neo, eksplorasi antar bidang masih dalam keadaan tidak teratur. Beberapa penjelajah membawa sampel materi, kristal energi, bahkan makhluk hidup dari bidang lain ke bidang自己 untuk diteliti, yang menyebabkan beberapa &quot;kecelakaan polusi antar bidang&quot; yang parah. Kasus yang paling terkenal adalah &quot;Kecelakaan Kristal Asing&quot; — sebuah kristal energi yang dibawa dari bidang manifestasi energi, karena parameter hukumnya tidak kompatibel dengan bidang自己, menyebabkan gangguan hukum yang berlangsung selama tiga tahun di jaringan hukum bidang自己, mengakibatkan anomali pada sistem kultivasi tiga wilayah bintang, dan puluhan ribu kultivator menderita kerusakan dalam berbagai tingkat. Penyelidikan setelahnya menunjukkan bahwa jika prinsip &quot;hanya mengembalikan pengetahuan&quot; diikuti pada saat itu, bencana ini sepenuhnya dapat dihindari.</p><p>Ide inti dari prinsip &quot;hanya mengembalikan pengetahuan&quot; adalah: pengetahuan adalah satu-satunya media yang aman dalam pertukaran antar peradaban. Materi dan energi membawa informasi hukum dari bidang asalnya, dan setelah memasuki lingkungan hukum yang berbeda dapat menyebabkan reaksi yang tidak terduga; sedangkan pengetahuan sebagai informasi abstrak, setelah pengkodean dan pemurnian yang tepat, dapat memisahkan jejak hukum dari bidang asalnya, dan menjadi sumber daya aman yang dapat dibagikan antar bidang.</p><h2 id="_2-definisi-dan-klasifikasi-pengetahuan" tabindex="-1">2. Definisi dan Klasifikasi &quot;Pengetahuan&quot; <a class="header-anchor" href="#_2-definisi-dan-klasifikasi-pengetahuan" aria-label="Permalink to &quot;2. Definisi dan Klasifikasi &quot;Pengetahuan&quot;&quot;">​</a></h2><p>Di bawah kerangka hukum prinsip &quot;hanya mengembalikan pengetahuan&quot;, &quot;pengetahuan&quot; memiliki definisi dan klasifikasi yang ketat. Tidak semua informasi dapat dianggap sebagai &quot;pengetahuan&quot; dan dikembalikan secara bebas — hanya informasi abstrak yang经过 proses &quot;pemurnian informasi&quot; dan dikonfirmasi tidak membawa polusi hukum apa pun yang memenuhi standar pengembalian.</p><p>Pengetahuan dibagi menjadi tiga kategori sesuai dengan tingkat abstraksi dan tingkat keamanannya:</p><table tabindex="0"><thead><tr><th>Kategori Pengetahuan</th><th>Definisi</th><th>Tingkat Keamanan</th><th>Persyaratan Pengembalian</th></tr></thead><tbody><tr><td>Pengetahuan tingkat pertama (pengetahuan abstrak murni)</td><td>Konsep abstrak yang sepenuhnya terlepas dari pembawa materi, teorema matematika, deduksi logis, pemikiran filosofis, dll.</td><td>Tertinggi (hijau)</td><td>Dapat dikembalikan langsung, tanpa persetujuan khusus</td></tr><tr><td>Pengetahuan tingkat kedua (pengetahuan deskriptif)</td><td>Informasi deskriptif tentang objek objektif, termasuk catatan sejarah, data geografis, karakteristik biologis, deskripsi budaya, dll.</td><td>Sedang (kuning)</td><td>Harus经过 proses pemurnian informasi, dikembalikan setelah disetujui oleh Biro Administrasi Bidang</td></tr><tr><td>Pengetahuan tingkat ketiga (pengetahuan teknis)</td><td>Pengetahuan praktis yang berisi parameter teknis spesifik, skema teknik, metode kultivasi</td><td>Lebih rendah (oranye)</td><td>Harus经过 pemurnian informasi ketat dan evaluasi keamanan, dikembalikan setelah persetujuan khusus dari Dewan Neo</td></tr></tbody></table><p>Konten berikut不属于 kategori &quot;pengetahuan&quot;, dan dilarang keras untuk dikembalikan: sampel materi dalam bentuk apa pun (termasuk mikroorganisme, sel, fragmen gen), kristal energi atau perangkat penyimpanan energi dalam bentuk apa pun, makhluk hidup atau tubuh kesadaran apa pun yang memiliki kesadaran otonom, data asli apa pun yang tidak经过 pemurnian informasi, dan detail teknis apa pun yang dapat digunakan untuk kultivasi predator.</p><h2 id="_3-teknologi-pemurnian-informasi" tabindex="-1">3. Teknologi Pemurnian Informasi <a class="header-anchor" href="#_3-teknologi-pemurnian-informasi" aria-label="Permalink to &quot;3. Teknologi Pemurnian Informasi&quot;">​</a></h2><p>Pemurnian informasi adalah tautan teknis kunci untuk memastikan keamanan pengetahuan yang dikembalikan. Tujuan intinya adalah memisahkan sepenuhnya jejak hukum bidang asal yang dibawa dalam informasi asli, hanya menyisakan konten semantik murni. Proses pemurnian informasi dibagi menjadi empat langkah:</p><h3 id="_3-1-dekonstruksi-informasi" tabindex="-1">3.1 Dekonstruksi Informasi <a class="header-anchor" href="#_3-1-dekonstruksi-informasi" aria-label="Permalink to &quot;3.1 Dekonstruksi Informasi&quot;">​</a></h3><p>Pertama, informasi asli yang akan dikembalikan didekonstruksi secara struktural, dipecah menjadi dua bagian: &quot;konten semantik&quot; dan &quot;jejak pembawa&quot;. Konten semantik adalah makna abstrak yang ingin disampaikan oleh informasi, jejak pembawa adalah parameter hukum bidang asal yang diserap oleh informasi selama proses penyimpanan dan transmisi. Dekonstruksi informasi实现 melalui &quot;algoritma pemisahan semantik-pembawa&quot;, algoritma ini dapat mengidentifikasi dan memisahkan komponen semantik dan komponen hukum dalam informasi.</p><h3 id="_3-2-pemisahan-hukum" tabindex="-1">3.2 Pemisahan Hukum <a class="header-anchor" href="#_3-2-pemisahan-hukum" aria-label="Permalink to &quot;3.2 Pemisahan Hukum&quot;">​</a></h3><p>Melakukan pemisahan hukum menyeluruh terhadap jejak pembawa yang telah dipisahkan. Metode pemisahan adalah melewatkan informasi melalui &quot;saluran netralisasi hukum&quot; — ini adalah saluran transmisi khusus yang parameter hukumnya diatur sepenuhnya netral, ketika informasi melewatinya, semua parameter hukum non-netral yang dibawanya akan diserap oleh dinding saluran. Setelah pemisahan hukum, informasi tidak lagi membawa jejak hukum bidang asal apa pun.</p><h3 id="_3-3-rekonstruksi-semantik" tabindex="-1">3.3 Rekonstruksi Semantik <a class="header-anchor" href="#_3-3-rekonstruksi-semantik" aria-label="Permalink to &quot;3.3 Rekonstruksi Semantik&quot;">​</a></h3><p>Berdasarkan pemisahan hukum, melakukan pengkodean ulang terhadap konten semantik, menggunakan sistem pengkodean informasi standar bidang自己 untuk merekonstruksi informasi. Rekonstruksi semantik memastikan bahwa pengetahuan yang dikembalikan dapat dibaca dan dipahami dengan benar di lingkungan hukum bidang自己,同时 juga进一步 menghilangkan struktur informasi bidang asal apa pun yang mungkin tersisa.</p><h3 id="_3-4-deteksi-keamanan" tabindex="-1">3.4 Deteksi Keamanan <a class="header-anchor" href="#_3-4-deteksi-keamanan" aria-label="Permalink to &quot;3.4 Deteksi Keamanan&quot;">​</a></h3><p>Informasi yang telah dimurnikan harus经过 deteksi keamanan yang ketat, termasuk: deteksi sisa hukum (memastikan informasi tidak membawa parameter hukum asing apa pun), deteksi integritas semantik (memastikan proses pemurnian tidak mengubah konten semantik informasi), dan evaluasi risiko potensial (mengevaluasi dampak sosial dan keamanan yang mungkin ditimbulkan oleh penyebaran pengetahuan ini di bidang自己). Hanya informasi yang lulus ketiga deteksi yang diizinkan untuk dikembalikan.</p><h2 id="_4-proses-pengembalian-dan-sistem-audit" tabindex="-1">4. Proses Pengembalian dan Sistem Audit <a class="header-anchor" href="#_4-proses-pengembalian-dan-sistem-audit" aria-label="Permalink to &quot;4. Proses Pengembalian dan Sistem Audit&quot;">​</a></h2><p>Pengembalian pengetahuan mengikuti manajemen proses yang ketat. Operasi pengembalian yang lengkap mencakup tautan berikut:</p><ol><li><strong>Penyusunan Pengetahuan</strong>: Tim arkeologi menyusun hasil penelitian menjadi dokumen pengetahuan standar, menandai dengan jelas kategori pengetahuan dan ringkasan konten.</li><li><strong>Permohonan Pemurnian</strong>: Mengajukan permohonan pemurnian dan pengembalian pengetahuan kepada Biro Administrasi Bidang atau Komite Hukum Waktu, melampirkan dokumen pengetahuan dan file izin tugas arkeologi.</li><li><strong>Pemurnian Informasi</strong>: Tim teknologi pemurnian informasi profesional melakukan proses pemurnian informasi empat langkah terhadap dokumen pengetahuan.</li><li><strong>Deteksi Keamanan</strong>: Pengetahuan yang telah dimurnikan经过 tiga deteksi yang dilakukan oleh lembaga deteksi keamanan independen.</li><li><strong>Persetujuan dan Pengembalian</strong>: Setelah lulus deteksi, lembaga persetujuan menandatangani izin pengembalian, pengetahuan dikembalikan ke basis data pengetahuan bidang自己 melalui saluran terenkripsi jaringan neo.</li><li><strong>Penyimpanan ke Arsip</strong>: Pengetahuan yang dikembalikan经过 verifikasi oleh basis pengetahuan bidang自己 kemudian secara resmi disimpan ke arsip, dibuka untuk peneliti yang memiliki izin yang sesuai.</li></ol><p>Semua operasi pengembalian harus接受 &quot;audit pengembalian&quot;. Konten audit mencakup: apakah sumber pengetahuan yang dikembalikan sah, apakah proses pemurnian sesuai norma, apakah deteksi keamanan lengkap, apakah prosedur persetujuan sesuai. Audit bertanggung jawab oleh Kantor Audit Pengembalian Pengetahuan di bawah Komite Pengawasan Neo, melakukan pemeriksaan sampel terhadap semua operasi pengembalian pada kuartal tersebut setiap kuartal, dan melakukan audit lengkap setahun sekali. Hasit audit dilaporkan kepada Dewan Neo, dan ringkasannya dipublikasikan kepada publik.</p><h2 id="_5-pelanggaran-dan-tanggung-jawab-hukum" tabindex="-1">5. Pelanggaran dan Tanggung Jawab Hukum <a class="header-anchor" href="#_5-pelanggaran-dan-tanggung-jawab-hukum" aria-label="Permalink to &quot;5. Pelanggaran dan Tanggung Jawab Hukum&quot;">​</a></h2><p>Perilaku yang melanggar prinsip &quot;hanya mengembalikan pengetahuan&quot; mencakup: mengembalikan informasi yang tidak dimurnikan tanpa persetujuan, menyamarkan sampel materi sebagai pengetahuan untuk dikembalikan, sengaja menyembunyikan jejak hukum bidang asal dalam pengetahuan yang dikembalikan, dan membantu orang lain melakukan pengembalian ilegal.</p><p>Berdasarkan &quot;Konstitusi Symbiosis&quot; dan &quot;Undang-Undang Manajemen Interaksi Antar Bidang&quot;, tanggung jawab hukum untuk pengembalian yang melanggar mencakup: penyitaan barang dan informasi yang dikembalikan secara melanggar, penangguhan atau pencabutan kualifikasi arkeologi dan penyeberangan pihak terkait, denda yang setara dengan lebih dari 10 kali nilai barang yang melanggar, hukuman penjara untuk kasus yang parah, dan harus menanggung semua biaya perbaikan dan tanggung jawab ganti rugi jika menyebabkan polusi hukum atau kerusakan ekologis.</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Prinsip &quot;hanya mengembalikan pengetahuan&quot; adalah garis bawah kebijaksanaan peradaban simbiosis neo di bidang interaksi antar bidang. Dengan definisi yang ketat, teknologi pemurnian yang matang, proses pengembalian yang sesuai norma, dan tanggung jawab hukum yang berat, ia membangun &quot;firewall keamanan pengetahuan&quot; yang kokoh. Makna prinsip ini tidak hanya在于 mencegah polusi pada tingkat fisik, yang lebih penting adalah menetapkan pandangan etika pertukaran antar peradaban — pertukaran antar peradaban harus berfokus pada benturan ide, bukan pada tujuan penjarahan materi.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>84-Garis Besar Protokol Arkeologi</li><li>88-Pedoman Etika Antar Bidang</li><li>66-Teknologi Komunikasi Antar Bidang</li></ul>',32)])])}const p=n(u,[["render",s]]);export{o as __pageData,p as default};
